const files=JSON.parse(gunzipSync(Buffer.from(encoded,'base64')).toString('utf8'));
const target=resolve(process.argv[2]||'hosted');
try { await lstat(target); throw Error('Choose a new empty destination; refusing to overwrite '+target); } catch(e) { if(e.code!=='ENOENT') throw e; }
for(const name of Object.keys(files)){const rel=relative(target,resolve(target,name));if(!rel||rel.startsWith('..')||isAbsolute(rel))throw Error('Unsafe path');}
await mkdir(target,{recursive:true});
for(const [name,content] of Object.entries(files)){const dest=join(target,name);await mkdir(dirname(dest),{recursive:true});await writeFile(dest,content,{flag:'wx'});}
console.log('Extracted '+Object.keys(files).length+' source files to '+target);
